import React from "react";
import {
  FaUser,
  FaPhone,
  FaMapPin,
  FaImage,
  Cpu,
  Tag,
  HelpCircle,
  Clock,
  Link2,
  FaChevronDown,
} from "react-icons/fa";

// استایل مشترک برای همه‌ی فیلدهای متنی/شماره
const fieldWrapClass =
  "flex items-center justify-between gap-3 w-full rounded-2xl border border-gray-300 bg-white px-4 py-3.5";
const inputClass =
  "flex-1 bg-transparent text-right text-[15px] text-gray-700 placeholder-gray-400 outline-none";
const iconClass = "shrink-0 text-gray-400 w-5 h-5";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      fullName: "",
      mobile: "",
      landline: "",
      province: "",
      address: "",
      deviceType: "",
      deviceBrand: "",
      deviceIssue: "",
      visitTime: "",
      description: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleChange(field) {
    return (e) => {
      this.setState({ [field]: e.target.value });
    };
  }

  handleSubmit(e) {
    e.preventDefault();
    // عمداً خالی گذاشته شده — منطق ساب‌میت بعداً اضافه می‌شود
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    return (
        <>
              <div dir="rtl" lang="fa" className="min-h-screen bg-[#f5f5f7] px-4 py-6">
        <div className="mx-auto w-full max-w-md">
          <h1 className="mb-6 text-center text-lg font-bold text-gray-900">
            اطلاعات مشتری را با دقت ثبت کنید
          </h1>

          <form onSubmit={this.handleSubmit} className="flex flex-col gap-4"/>

            <div className={fieldWrapClass}>
              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
                className={inputClass}
              />
              <FaUser className={iconClass} />
            </div>

            {/* شماره موبایل */}
            <div className={fieldWrapClass}>
              <input
                type="tel"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
                className={inputClass}
              />
              <FaPhone className={iconClass} />
            </div>

            {/* تلفن ثابت */}
            <div className={fieldWrapClass}>
              <input
                type="tel"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
                className={inputClass}
              />
              <FaPhone className={iconClass} />
            </div>

            {/* استان */}
            <div className={fieldWrapClass}>
              <FaChevronDown className="shrink-0 text-gray-400 w-5 h-5" />
              <select
                value={province}
                onChange={this.handleChange("province")}
                className={{inputClass}}
              >
                <option value="" disabled hidden>
                  استان
                </option>
                <option value="tehran">تهران</option>
                <option value="isfahan">اصفهان</option>
                <option value="fars">فارس</option>
                <option value="khorasan-razavi">خراسان رضوی</option>
                <option value="alborz">البرز</option>
              </select>
              <FaMapPin className={iconClass} />
            </div>

            {/* آدرس */}
            <div className={fieldWrapClass}>
              <input
                type="text"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
                className={inputClass}
              />
              <ImageOff className={iconClass} />
            </div>
{/* نوع دستگاه */}
            <div className={fieldWrapClass}>
              <FaChevronDown className="shrink-0 text-gray-400 w-5 h-5" />
              <select
                value={deviceType}
                onChange={this.handleChange("deviceType")}
                className={{inputClass} }
              >
                <option value="" disabled hidden>
                  نوع دستگاه
                </option>
                <option value="washer">ماشین لباسشویی</option>
                <option value="fridge">یخچال</option>
                <option value="ac">کولر گازی</option>
                <option value="tv">تلویزیون</option>
              </select>
              <Cpu className={iconClass} />
            </div>

            {/* برند دستگاه */}
            <div className={fieldWrapClass}>
              <FaChevronDown className="shrink-0 text-gray-400 w-5 h-5" />
              <select
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
                className={{inputClass} }
              >
                <option value="" disabled hidden>
                  برند دستگاه
                </option>
                <option value="samsung">سامسونگ</option>
                <option value="lg">ال‌جی</option>
                <option value="snowa">اسنوا</option>
                <option value="pakshoma">پاکشوما</option>
              </select>
              <Tag className={iconClass} />
            </div>

            <div className={fieldWrapClass}>
              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
                className={inputClass}
              />
              <HelpCircle className={iconClass} />
            </div>

            {/* زمان مراجعه */}
            <div className={fieldWrapClass}>
              <input
                type="text"
                placeholder="زمان مراجعه"
                value={visitTime}
                onChange={this.handleChange("visitTime")}
                className={inputClass}
              />
              <Clock className={iconClass} />
            </div>

            {/* توضیحات */}
            <div className={fieldWrapClass}>
              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
                className={inputClass}
              />
              <Link2 className={iconClass} />
            </div>

            {/* دکمه ثبت */}
            <button
              type="submit"
              className="mt-2 w-full rounded-2xl bg-blue-600 py-3.5 text-center text-[15px] font-medium text-white transition hover:bg-blue-700"
            >
              ثبت درخواست
            </button>
          <form/>
        </div>
      </div>
      </>
    );
  }
}

export default CustomerRequestForm;
